package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamAnuradhapuraSculptureBank2 {
    private const val T = "අනුරාධපුර යුගයේ මූර්ති හා කැටයම් කලාව"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("අනුරාධපුර ඉසුරුමුණි විහාර කෞතුකාගාරයේ ඇති ලෝක ප්‍රකට 'ඉසුරුමුණි පෙම් යුවළ' කැටයම අයත් වන්නේ කුමන කලා සම්ප්‍රදායටද?", "ඉන්දියානු ගුප්ත කලා ආභාසය ලැබූ ක්‍රි.ව. 5–6 සියවස් කලාව", "මහනුවර ජන ගැමි කැටයම් සම්ප්‍රදාය", "පෘතුගීසි බැරොක් කැටයම් සම්ප්‍රදාය", "ප්‍රාග් ඓතිහාසික ගුහා කෙටුම්", "ලාලිත්‍යමය ගුප්ත ආභාසයෙන් යුත් ඉසුරුමුණි පෙම් යුවළ ලෞකික මූර්ති කලාවේ අග්‍රගණ්‍ය නිර්මාණයකි."),
        q("ඉසුරුමුණි පෙම් යුවළ කැටයමින් නිරූපණය වන චරිත දෙක පිළිබඳව මහාචාර්ය පරණවිතානයන් ඉදිරිපත් කළ මතය කුමක්ද?", "දුටුගැමුණු රජුගේ පුත් සාලිය කුමරු සහ අශෝකමාලා දේවිය", "පරාක්‍රමබාහු රජු සහ ලීලාවතී රැජින", "විජය රජු සහ කුවේණිය", "සිදුහත් කුමරු සහ යශෝධරා දේවිය", "සාලිය කුමරු හා අශෝකමාලාගේ ප්‍රේම වෘත්තාන්තය ඉන් නිරූපිත බව පරණවිතාන මතයයි."),
        q("ඉසුරුමුණි පෙම් යුවළ කැටයම සම්බන්ධයෙන් පවතින තවත් ප්‍රධාන විද්වත් අර්ථකථනයක් කුමක්ද?", "සිව හා පාර්වතී හෝ මංජුශ්‍රී බෝසතුන් හා තාරා දේවිය", "මහසෙන් රජු හා නාග කන්‍යාව", "මනමේ කුමරු හා වැදි රජු", "රාමා හා සීතා දේවිය", "යුද පලිහක් වැනි අංගයක් පිටුපසින් ඇති නිසා හමුදාපතිවරයෙකු හා බිරිඳ හෝ ශිව-පාර්වතී යැයිද මත ඇත."),
        q("ඉසුරුමුණි පෙම් යුවළ කැටයම් කර ඇති කළුගල් පුවරුවෙහි භාවිත කළ මූර්ති තාක්ෂණය කුමක්ද?", "උන්නත කැටයම් ක්‍රමය (High/Bas Relief)", "පූර්ණ වටකුරු මූර්ති ක්‍රමය", "ලෝකඩ ඉටි මැකුම් වාත්තු ක්‍රමය", "මැටි පිළිස්සුම් ක්‍රමය", "පාෂාණ පුවරුවක් මතුපිටින් පසුබිම හාරා රූප ඉදිරියට මතු කරන උන්නත කැටයම් ක්‍රමය යොදා ඇත."),
        q("ඉසුරුමුණි පෙම් යුවළ කැටයමේ කාන්තා රුවෙහි උරහිස අසල පිහිටි පුරුෂ රුවට 'ලැජ්ජාශීලී අභිනය' පළ කරන්නේ කුමන ඉරියව්වකින්ද?", "මඳක් ඉවතට හැරී අතින් තර්ජනී හෝ සියුම් ඇඟිලි ඉරියව්වක් පෑමෙන්", "මුහුණ සම්පූර්ණයෙන් රෙද්දකින් වසා ගැනීමෙන්", "පුරුෂයාට පිටුපා නැගිට සිටීමෙන්", "දෙඅත් හිස මත තබා හැඬීමෙන්", "කාන්තාවගේ අත් සංඥාව හා නැමුණු හිස කැටයමට අපූරු සජීවී ප්‍රේමාන්විත හැඟීමක් ගෙන දෙයි."),
        q("ඉසුරුමුණි විහාර පරිශ්‍රයේ පිහිටි 'මිනිසා සහ අශ්ව හිස' කැටයම කුමන ඉන්දීය කලා සම්ප්‍රදායට බෙහෙවින් සමානද?", "පල්ලව කලා සම්ප්‍රදාය (ක්‍රි.ව. 7 වන සියවස)", "චෝල ලෝකඩ සම්ප්‍රදාය", "මූගල් කලා සම්ප්‍රදාය", "සාංචි බෞද්ධ සම්ප්‍රදාය", "දකුණු ඉන්දියාවේ මහාබලිපුරම් පල්ලව ශෛලියට සමාන තේජස්වී බවක් මෙම කැටයමේ ඇත."),
        q("ඉසුරුමුණියේ 'මිනිසා සහ අශ්ව හිස' කැටයමෙන් නිරූපණය වන්නේ කුමන සංකල්ප බව පරණවිතානයන් පැවසුවේද?", "පර්ජන්‍ය හා අග්නි හෝ සෙනෙවියෙක්", "කණ්ඨක අශ්වයා හා චන්න ඇමති", "සිංහබාහු හා සිංහයා", "වෙස්සන්තර රජු හා ඇතා", "පර්ජන්‍ය හා අග්නි දෙවිවරුන් නිරූපණය කරන බව පරණවිතාන මතය වන අතර කපිල සෘෂි යැයිද මතයකි."),
        q("ඉසුරුමුණියේ 'මිනිසා සහ අශ්ව හිස' කැටයමේ පුරුෂයා වාඩි වී සිටින ඉරියව්ව හඳුන්වන්නේ කුමන නමින්ද?", "මහාරාජලීලාසනය", "වීරාසනය", "පද්මාසනය", "භද්‍රාසනය", "එක් දණහිසක් ඔසවා අනෙක් පාදය නවා නිදහස්ව අත තබා සිටින ඉරියව්ව මහාරාජලීලාසනය නම් වේ."),
        q("ඉසුරුමුණියේ පොකුණ අසල පර්වතයේ නෙළා ඇති 'දිය කෙළියේ යෙදෙන ඇතුන්' කැටයමේ විශේෂත්වය කුමක්ද?", "පර්වතයේ ස්වභාවික හැඩය යොදාගෙන ජලයේ කෙළින ඇතුන් සජීවීව දැක්වීම", "ඇතුන්ට ඔටුණු පළඳවා තිබීම", "ඇතුන් ලෝකඩවලින් වාත්තු කර තිබීම", "ඇතුන් පිට යුද භටයන් සිටීම", "පල්ලව ආභාසය ලත් මෙම කැටයමින් පොකුණේ ජලය පෙන ඉහළට විදින ඇතුන් ස්වභාවිකව නෙළා ඇත."),
        q("ඉසුරුමුණියේ ඇති තවත් ප්‍රකට කැටයමක් වන 'රාජ සභාව හෙවත් රාජ පවුල' කැටයමේ සිටින ප්‍රධාන පුද්ගලයා වටා සිටින අනෙක් රූප කවුද?", "බිසව, පිරිවාර කාන්තාවන් හා සේවක පිරිස", "සිංහයන් හා කොටියන් පමණි", "භික්ෂූන් වහන්සේලා පස්නම", "රෝම සෙබළුන් හතරදෙනා", "මහාරාජලීලාසනයෙන් සිටින ප්‍රභූ පුරුෂයා හා පරිවාර රූප කිහිපයක් එම ශිලා පුවරුවේ වේ."),
        q("අනුරාධපුර යුගයේ විහාරස්ථාන පියගැටපෙළ පාමුල ඇති 'සඳකඩපහණ' (Moonstone) මගින් සංකේතවත් කෙරෙන බෞද්ධ දර්ශනය කුමක්ද?", "සංසාර චක්‍රය හා එයින් මිදී නිර්වාණය වෙත ළඟා වීම", "රජුගේ බල පරාක්‍රමය හා යුද ශක්තිය", "කෘෂිකාර්මික වාරි තාක්ෂණය", "සෘතු වෙනස් වීම හා කාලගුණය", "සංසාරයේ ගමන හා කෙලෙස් දවා නිවන් පුරයට පිවිසීම අර්ධ වෘත්තාකාර සඳකඩපහණින් දැක්වේ."),
        q("අනුරාධපුර යුගයේ සඳකඩපහණෙහි පිටතින්ම ඇති රවුම් තීරුවේ කැටයම් කර ඇති සැරසිල්ල කුමක්ද?", "පලාපෙති හෙවත් ගිනිසිළු මෝස්තරය", "හංස පෙළ මෝස්තරය", "ලියවැල් මෝස්තරය", "මකර රූප පෙළ", "පිටතින්ම පිහිටි ගිනිදැල් හෙවත් පලාපෙති තීරුව කෙලෙස් ගින්න හෝ තණ්හාව සංකේතවත් කරයි."),
        q("අනුරාධපුර සඳකඩපහණෙහි සත්ව පෙළෙහි දක්නට ලැබෙන සතුන් සතර දෙනා නිවැරදිව දැක්වෙන පිළිතුර කුමක්ද?", "ඇතා, අශ්වයා, සිංහයා සහ ගවයා", "ඇතා, අශ්වයා, සිංහයා සහ හංසයා", "මුවා, සිංහයා, ගවයා සහ කොටියා", "අශ්වයා, මකරා, සිංහයා සහ ගවයා", "අනුරාධපුර සඳකඩපහණේ ගවයා ඇතුළු සතුන් සතර දෙනා එකම තීරුවේ ගමන් කරන සේ කැටයම් කර ඇත."),
        q("මහාචාර්ය පරණවිතානයන්ගේ අර්ථකථනයට අනුව සඳකඩපහණේ ඇති ඇතා, අශ්වයා, සිංහයා සහ ගවයා යන සතුන් සංකේතවත් කරන්නේ කුමක්ද?", "ජාති, ජරා, ව්‍යාධි සහ මරණ යන සතර දුක් හෙවත් සසර භව ගමන", "සතර සෘතු හා සතර මහා ද්වීප", "වෙළඳ, ගොවි, බමුණු හා ක්ෂත්‍රිය කුල", "රජුගේ ඇත්, අස්, රිය, පාබල සේනාව", "ජාති (ඇතා), ජරා (අශ්වයා), ව්‍යාධි (සිංහයා) හා මරණ (ගවයා) ලෙස ඔහු සංකේතාර්ථය පැහැදිලි කර ඇත."),
        q("අනුරාධපුර සඳකඩපහණෙහි සතුන් සතර දෙනාගේ තීරුවට ඇතුළතින් ඇති සැරසිලි තීරු දෙක කුමක්ද?", "ලියවැල් තීරුව හා කෙසෙල් මුල්/මල් ඩැහැගත් හංස පෙළ", "යුද අශ්ව රථ පෙළ හා සොල්දාදුවන්", "සිංහ හිස් හා මකර රූප", "ගණ රූප හා නාගරාජ රූප", "ලියවැල තෘෂ්ණාවද හංස පෙළ හොඳ නරක වෙන් කර ගැනීමේ ඥානයද සංකේතවත් කරයි."),
        q("අනුරාධපුර සඳකඩපහණෙහි හරි මැද කේන්ද්‍රයේ කැටයම් කර ඇති පිපුණු මල කුමක්ද?", "අර්ධ නෙළුම් මල (පද්මය)", "සූරියකාන්ත මල", "කඩුපුල් මල", "සපු මල", "සඳකඩපහණේ මැද ඇති අර්ධ පද්මය සියලු කෙලෙස් ඉක්මවූ නිර්වාණ පාරිශුද්ධිය සංකේතවත් කරයි."),
        q("ශ්‍රී ලංකාවේ දැනට හමුවන ඉතාම අලංකාර හා විශිෂ්ටතම අනුරාධපුර සඳකඩපහණ පිහිටා ඇත්තේ කොතැනද?", "අනුරාධපුර බිසෝ මාලිගය හෙවත් මහාසේන මන්දිරය අබියස", "පොළොන්නරුවේ වටදාගෙය අබියස", "මහනුවර දළදා මාලිගාව අබියස", "දඹුල්ල රජමහා විහාරය අබියස", "මහසෙන් මාලිගය ඉදිරිපිට ඇති සඳකඩපහණ කැටයම් තියුණු බවින් හා සමබරතාවයෙන් විශිෂ්ටතම එකකි."),
        q("අනුරාධපුර යුගයේ 'මුරගල' (Guardstone) කලාවේ ආරම්භක පළමු අවධියේදී එහි දැකිය හැකි වූයේ කුමක්ද?", "කැටයම් රහිත අර්ධ වෘත්ත ගල් පුවරුව", "සත් මුහුණත් නාගරාජ රුව", "වාමන රූප දෙකක් සහිත පුවරුව", "සිංහයෙකු පිට නැගුණු රජෙක්", "මුල් යුගයේ මුරගල් කැටයම් රහිත චාම් පාෂාණ පුවරු ලෙස පැවති අතර පසුව පුන්කලස් හා නාගරාජ රූප එක්විය."),
        q("මුරගල විකාශනයේ දෙවන අවධියේදී හිස් ගල් පුවරුව මත කැටයම් කළ ප්‍රධාන සෞභාග්‍ය සංකේතය කුමක්ද?", "පුන් කලස හෙවත් පූර්ණ ඝටය", "අසිපත හා පළිහ", "චක්‍රාවාට මණ්ඩලය", "හංස පූට්ටුව", "නෙළුම් මල් පිරුණු පුන්කලස සශ්‍රීකත්වය හා මංගල සම්මතය සංකේතවත් කරමින් දෙවන අවධියේ එක් විය."),
        q("මුරගල විකාශනයේ තෙවන අවධියේදී පුන් කලසට පසුව මුරගලෙහි කැටයම් කරන ලද චරිත මොනවාද?", "සංඛ හා පද්ම නම් බහිරව (ගණ) රූප", "පෘතුගීසි හේවායන්", "බුදු පිළිම යුගල", "සිංහ හා ගව රූප", "ධන කුවේරයාගේ නිධන් ආරක්ෂකයන් වන සංඛ සහ පද්ම යන බහිරව රූප හිස්වැසුම් සහිතව මුරගලට එක් විය."),
        q("අනුරාධපුර යුගයේ මුරගල විකාශනයේ උච්චතම හතරවන අවධියේදී නෙළා ඇති ප්‍රධාන රූපය කුමක්ද?", "මිනිස් වෙස් ගත් පංච හෝ සප්ත පෙණ නාගරාජ රුව", "කැටයම් කළ කුරුලු කූඩුවක්", "ගජසිංහ මූර්තියක්", "පත්තිනි දේවතාවියගේ රුවක්", "හිසට පිටුපසින් නාග පෙණ හතක් ඇති අලංකාර ආභරණ පැළඳි නාගරාජ මුරගල උච්චතම අවධියයි."),
        q("අනුරාධපුර රත්නප්‍රාසාදය ඉදිරිපිට ඇති ලෝක ප්‍රකට මුරගල විශේෂිත වන්නේ කුමන කලා ගුණාංගය නිසාද?", "අතිශය සියුම් කැටයම්, ත්‍රිභංග ඉරියව්ව හා මනරම් මකර තොරණ නිසා", "කැටයම් රහිත සම්පූර්ණ සමතලා ගලක් නිසා", "එය ලෝකඩවලින් සාදා ඇති නිසා", "එහි සිංහල අකුරු පමණක් කොටා ඇති නිසා", "රත්නප්‍රාසාද මුරගල අනුරාධපුර කැටයම් ශිල්පියාගේ විශිෂ්ටතම කලා කෘතියක් ලෙස සැලකේ."),
        q("නාගරාජ මුරගලෙහි නාගරාජයා දෑතින් දරා සිටින සෞභාග්‍යමය වස්තූන් දෙක මොනවාද?", "එක් අතකින් පුන්කලසක්ද අනෙක් අතින් මල් අත්තක්ද", "එක් අතකින් කඩුවක්ද අනෙක් අතින් පළිහක්ද", "දෙඅතින්ම පොත් මිටියක්ද", "එක් අතකින් බෙරයක්ද අනෙක් අතින් තාලම්පටක්ද", "පුන්කලස හා මල් ලියවැලක් දරමින් ආරක්ෂාව හා සෞභාග්‍යය පතා සිටිනු නෙළා ඇත."),
        q("නාගරාජ මුරගලෙහි නාගරාජයාගේ පාද පාමුල කුඩාවට නෙළා ඇති රූපය කවුරුන්ද?", "විවිධ ඉරියව්වලින් සිටින වාමන හෙවත් බහිරව රූප", "පිහිනන මසුන් රංචුවක්", "නිදා සිටින දඩයම් බල්ලෙක්", "කුඩා සිංහ පැටවුන් පස්දෙනෙක්", "මුරගලේ පාමුල කොණේ නාගරාජයා දෙස බලා සිටින කුඩා ගණ හෝ වාමන රූපයක් කැටයම් කර ඇත."),
        q("මුරගලට පිටුපසින් පියගැටපෙළ දෙපස ඇති අලංකාර අත්වැල හඳුන්වනු ලබන්නේ කුමන නමින්ද?", "කොරවක්ගල (Balustrade)", "වටදාගෙය", "සඳකඩපහණ", "වාහල්කඩ", "පියගැටපෙළ දෙපස පිහිටි කොරවක්ගල්වල ඉදිරි කොටසේ මකර මුඛයකින් පිටවන ලියවැල් ඇත."),
        q("අනුරාධපුර යුගයේ 'කොරවක්ගල' මත බහුලව කැටයම් කර ඇති මිථ්‍යා සත්වයා කවුද?", "මකරා (Makara)", "භේරුණ්ඩ පක්ෂියා", "පියාපත් ඇති අශ්වයා", "ජල කිඳුරා", "කිඹුලා, ඇතා, සිංහයා හා මත්ස්‍ය අංග එකතු වූ මකරාගේ මුඛයෙන් පහළට ගලන ලියවැල කොරවක්ගලේ අංගයකි."),
        q("අනුරාධපුර යුගයේ 'වටදාගේ' හෝ පියගැටපෙළවල සිරස් තලයේ (Risers) කැටයම් කර ඇති රූප මොනවාද?", "සංගීත භාණ්ඩ වයන හා නටන වාමන රූප පෙළ", "කෘෂිකාර්මික සිතියම් පෙළ", "බුදුන් වහන්සේගේ පිරිනිවන් මංචකය", "නැව් සහ මුහුදු යාත්‍රා", "පඩිපෙළේ ඉදිරි සිරස් මුහුණතේ පවා විවිධ ඉරියව්වලින් සිටින ගණ රූප කැටයම් කර අලංකාර කර ඇත."),
        q("ඉසුරුමුණි විහාර කෞතුකාගාරයේ ඇති කැටයම් අතර 'පෙම් යුවළ' පුවරුවේ ඉහළින් කුඩාවට පෙනෙන ලක්ෂණය කුමක්ද?", "පිටුපසින් ඇති කඩුව හා පළිහ වැනි සංකේතය", "රන් ආලේපිත ඔටුන්න", "සිංහල අක්ෂර පෙළ", "විශාල මකර හිස", "පුරුෂයාගේ උරහිසට පිටුපසින් කඩු මිට හෝ පළිහක් වැනි කොටසක් දිස් වීම විචාරයේදී සැලකිල්ලට ගැනේ."),
        q("අනුරාධපුර යුගයේ 'සඳකඩපහණ, මුරගල සහ කොරවක්ගල' යන අංග තුනම එකට පිහිටන්නේ කුමන ස්ථානයකද?", "විහාර හා ප්‍රාසාද ගොඩනැගිලිවල ප්‍රධාන පිවිසුම් දොරටුවේදී", "දාගැබේ කොත් කැරැල්ල මුදුනේදී", "වැව් බැම්මේ සොරොව්ව ඇතුළතදී", "සංඝාවාසයේ මුළුතැන්ගෙයිදී", "මෙම වාස්තු කලා අංග ත්‍රිත්වයම බෞද්ධ ගොඩනැගිලිවල පියගැටපෙළ පිවිසුම අලංකාර කරයි."),
        q("අනුරාධපුරයේ 'ලෝවාමහාපාය' හෝ 'මහා විහාර' ආශ්‍රිත ගොඩනැගිලිවල දක්නට ලැබෙන 'කුළුණු හිස්' කැටයම කුමක්ද?", "සියුම් නෙළුම් පෙති හා පලාපෙති රටා", "බටහිර කොරින්තියානු කොළ රටා", "මහනුවර පෙරහැරේ ඇතුන් රටා", "චීන පිඟන් කැටයම් රටා", "පැතලි ශිලා කුළුණු හිස් මත පහළට නැමුණු නෙළුම් පෙති හා කුඩා මල් රටා අලංකාරව කැටයම් කර තිබේ."),
        q("අනුරාධපුර යුගයේ 'කැසිකිළි ගල්' (Urinal stones) මත පවා විශිෂ්ට වාස්තු කැටයම් කොටා තිබුණේ කුමන ආරාමවලද?", "අනුරාධපුර අරණ්‍යවාසී පංචාවාස හා තපෝවන ආරාමවල", "මහනුවර දළදා මාලිගාවේ", "සීගිරි ජල උද්‍යානයේ", "ගාල්ල ලන්දේසි කොටුවේ", "බටහිර ආරාමවල රාජකීය ප්‍රාසාදවල ආකෘති කැටයම් කර තිබීම ලෞකික සැපය පිළිකුල් කිරීම සංකේතවත් කළේය."),
        q("බටහිර ආරාමවල කැසිකිළි ගල්වල විශාල මාලිගා කැටයම් කර තිබීමෙන් භික්ෂූන් වහන්සේලාට ලබා දුන් ආධ්‍යාත්මික පණිවිඩය කුමක්ද?", "ලෞකික රාජ සැප සම්පත් අපවිත්‍ර හා නිසරු දේ ලෙස සැලකීම", "රාජ මාලිගාවලට ගරු බුහුමන් දැක්වීම", "වඩු කර්මාන්තය ඉගැන්වීම", "ගෘහ නිර්මාණ සැලසුම් විකිණීම", "සංසාරික කාමභෝගී මන්දිර කෙරෙහි ඇති ඇල්ම දුරු කිරීම පංශුකූලික භික්ෂූන්ගේ අරමුණ විය."),
        q("අනුරාධපුර යුගයේ 'කුට්ටම් පොකුණ' ගල් බැමිවල ඇති ඉතාම අලංකාර ජල නළ කැටයම කුමක්ද?", "මකර මුඛයෙන් ජලය එන පීල්ල", "නූතන පිත්තල කරාමය", "සිංහ හිසින් ගිනි පිටවන කැටයම", "හංස පූට්ටු ජල පීල්ල", "අභයගිරි විහාර සංකීර්ණයේ කුට්ටම් පොකුණට ජලය වැටෙන්නේ මකර මුඛ කැටයමක් තුළිනි."),
        q("අනුරාධපුරයේ පිහිටි 'සඳකඩපහණෙහි' භාවිත කළ පලාපෙති හෙවත් ගිනිසිළු තීරුව හා ඇතුන්ගේ තීරුව අතර සම්බන්ධය කුමක්ද?", "සසර පුරා දැවෙන කෙලෙස් ගින්න හා දුක් පරම්පරාව පෙන්වීම", "වනයේ ඇති වූ ලැව් ගින්නකින් සතුන් දුවන අයුරු පෙන්වීම", "රජුගේ අශ්ව හමුදාව පෙළපාලි යන අයුරු", "සත්ව උද්‍යානයක සීමා වැට පෙන්වීම", "කෙලෙස් ගිනි තුළින් භව චක්‍රයේ සැරිසරන සත්වයාගේ දුක එම කැටයම් මාලාවෙන් පැහැදිලි වේ."),
        q("අනුරාධපුර 'අභයගිරියේ' හා 'ජේතවනාරාමයේ' වාහල්කඩ කුළුණු මත සිටින සිංහ රූපවල ශෛලිය කෙබඳුද?", "සම්භාව්‍ය අශෝක හා අමරාවතී ආභාසය ගත් ගාම්භීර ස්වභාවය", "මහනුවර යුගයේ හාස්‍යජනක සිංහ රූප", "චීන සෙරමික් සිංහ රූප", "ප්‍රාග් ඓතිහාසික කූරු රූප", "ඉදිරිපසට පපුව පුම්බා තේජස්වීව සිටින සිංහ මූර්ති ආරක්ෂක සංකේත ලෙස නෙළා ඇත."),
        q("ඉසුරුමුණි විහාරයේ 'පෙම් යුවළ' මූර්තියෙහි කාන්තා රුවෙහි හිස පැත්තට ඇලවී තිබීමෙන් මූර්තියට ලැබෙන කලාත්මක අගය කුමක්ද?", "දැඩි ගල් පුවරුවකට මෘදු සජීවී මානුෂීය හැඟීමක් හා රිද්මයක් ලැබීම", "ගල කැඩී යාමෙන් හිස ඇල වී තිබීම", "පුරුෂයා කාන්තාවට පහර දීමට සැරසෙන බව පෙන්වීම", "කාන්තාව නිදා සිටින බව දැක්වීම", "හිසේ නැමීම හා ත්‍රිභංග දේහ විලාසය දෘඪ කළුගලකින් මෘදු ප්‍රේමය නිරූපණය කරයි."),
        q("අනුරාධපුර යුගයේ 'මුරගල' කැටයමෙහි නාගරාජ රුවට ඉහළින් කැටයම් කර ඇති 'මකර තොරණ' කුමක් සඳහා යොදා ඇත්ද?", "ප්‍රධාන දේව රුවට උත්තරීතර අලංකාරයක් හා රාමුවක් ලබා දීමට", "වැසි වතුර එකතු කිරීමට", "නාගරාජයා සිර කර තැබීමට", "කුරුල්ලන්ට කූඩු තැනීමට", "රත්නප්‍රාසාද හා වටදාගේ මුරගල්වල නාගරාජයාට ඉහළින් මනරම් මකර තොරණක් නෙළා ඇත."),
        q("අනුරාධපුර යුගයේ 'සඳකඩපහණේ හංස පෙළ' විශේෂයෙන්ම වැදගත් වන්නේ හංසයින්ගේ මුවෙහි තිබෙන කුමන දෙය නිසාද?", "නෙළුම් මල් හෝ නෙළුම් දඬු", "මසුන් හා කකුළුවන්", "රන් කාසි මලු", "ගිනි පන්දම්", "නෙළුම් මල් පොහොට්ටු ඩැහැගත් හංස පෙළ මඩෙන් කිරි වෙන් කරන සත්පුරුෂ ඥානය සංකේතවත් කරයි."),
        q("අනුරාධපුර යුගයේ මූර්ති ශිල්පීන් 'ගල් කැටයම් කෙටීමට' යොදා ගත් ප්‍රධාන උපකරණ මොනවාද?", "විවිධ ප්‍රමාණයේ යකඩ හා වානේ කටු (Chisels) සහ මිටි", "ලේසර් කිරණ කැපුම් යන්ත්‍ර", "දැව කියත් සහ යතු කැට", "මැටි පිළිස්සුම් අච්චු", "පැරණි ලංකාවේ දියුණු වානේ තාක්ෂණය (වූට්ස් වානේ) තද ග්නයිස් ගල් කැටයම් කිරීමට ඉවහල් විය."),
        q("අනුරාධපුර යුගයේ 'පුන්කලස' කැටයම දක්නට ලැබෙන්නේ කුමන වාස්තු අංගවලද?", "මුරගල්, දොරටු උළුවහු සහ කුට්ටම් පොකුණ බැමිවල", "කැසිකිළි ගල් ඇතුළත පමණක්", "සිවුරු රැලි අතර පමණක්", "වැව් බැම්ම යට පමණක්", "සෞභාග්‍යය හා පිරිපුන් බව පතා විහාර පිවිසුම් මුරගල් හා කුළුණුවල පුන්කලස් කැටයම් කර ඇත."),
        q("අනුරාධපුර 'අභයගිරි විහාරය' හා 'මහා විහාරය' අතර පැවති ආගමික වෙනස්කම් මූර්ති කලාවට බලපෑ ආකාරය කුමක්ද?", "අභයගිරිය ආශ්‍රිතව මහායාන බෝධිසත්ව රූප හා විවිධ මුද්‍රා වැඩිපුර දක්නට ලැබීම", "මහා විහාරයේ කිසිදු බුදු පිළිමයක් නොතිබීම", "අභයගිරියේ සතුන්ගේ රූප පමණක් නෙළීම", "මහා විහාරයේ සියලු පිළිම ලෝකඩ වීම", "ථේරවාද හා මහායාන සම්ප්‍රදායන් දෙකම මෙරට බෞද්ධ මූර්ති විවිධත්වයට හේතු විය."),
        q("අනුරාධපුර 'මිහින්තලේ සිංහ පොකුණ' හි ඇති විශාල සිංහ කැටයම කලාත්මකව විශේෂිත වන්නේ ඇයි?", "දෙපා පෙරට තැබූ මහා ජල මූර්තිය", "පියාපත් හතරක් ඇති සිංහ රුව", "මිනිස් මුහුණක් ඇති සිංහ රුව", "මැටියෙන් සෑදූ කුඩා රුව", "භික්ෂූන් පැන් සැපයීමට තැනූ පොකුණ අලංකාර කිරීමට සිංහ කටින් ජලය ගලන සේ නෙළා ඇත."),
        q("ඉසුරුමුණි විහාරයේ 'පෙම් යුවළ' පුවරුවේ ඉඩ ප්‍රමාණයෙන් වැඩි කොටසක් පුරවා ඇති ප්‍රධාන විලාසය කුමක්ද?", "සිහින් හා සුමට ශරීර අනුපාත සහිත ලාලිත්‍යමය හිඳි ඉරියව්ව", "පසුබිමේ ඇඳ ඇති විශාල ගස් හා කඳු පෙළ", "වටේට ඇති අකුරු පේළි සියය", "බහු මුහුණු හා අත් දහය බැගින් ඇති රූප", "පසුබිම් සැරසිලි අවම කර චරිත දෙකේ හැඟීම් ප්‍රකාශනයට මුළු පුවරුවම වෙන් කර ඇත."),
        q("අනුරාධපුර යුගයේ 'වටදාගෙවල්' වල බුදු පිළිමවලට ඉහළින් කළුගලින් තනා තිබූ ආවරණය කුමක්ද?", "දැව හා උළු වහලැති ශිලා කුළුණු", "තනි වීදුරු ගෝලාකාර වහලය", "රන් තහඩු කූඩාරම", "මැටි පිදුරු වහලය පමණක්", "ථූපාරාමය, ලංකාරාමය වැනි වටදාගෙවල්වල දාගැබ හා බුදු පිළිම වටා කේන්ද්‍රගත ගල් කුළුණු පේළි විය."),
        q("අනුරාධපුර යුගයේ 'ලෝකඩ ප්‍රතිමා' කලාවේදී ඉටි මැකුම් ක්‍රමයේදී 'ඉටි ආකෘතිය' වටා ආලේප කළේ කුමක්ද?", "මැටි හා ගඩොල් කුඩු බදාමය", "සීනි සහ පාන් පිටි මිශ්‍රණය", "රසදිය හා සින්ක් දියර", "ලී කුඩු සහ තෙල්", "මී ඉටියෙන් සැදූ ප්‍රතිමාව වටා මැටි ආවරණයක් ගා පුළුස්සා ඉටි ඉවත් කර උණු ලෝකඩ වත් කරනු ලැබේ."),
        q("අනුරාධපුර යුගයේ මූර්ති කලාවේ 'බෝධිසත්ව රූප' හා 'බුදු පිළිම' වෙන් කර හඳුනාගත හැකි ප්‍රධාන බාහිර ලක්ෂණය කුමක්ද?", "බෝධිසත්ව රූපවල රාජාභරණ හා උස් ජටා මකුට ඔටුනු පැවතීම", "බෝධිසත්ව රූපවලට අත් නොතිබීම", "බුදු පිළිමවල සෑම විටම ඔටුණු පැළඳ තිබීම", "බෝධිසත්ව රූප සියල්ල සතුන්ගේ රූප වීම", "බුදු පිළිම චීවරයෙන් හා සරල හිසින් යුක්ත වන අතර බෝසත් රූප රාජාභරණ හා ඔටුන්නෙන් සැරසී ඇත."),
        q("අනුරාධපුර යුගයේ 'ශිලා මූර්ති' කැටයම්කරුවා පාෂාණ තෝරා ගැනීමේදී පෙන්වූ භූ විද්‍යාත්මක දැනුම කුමක්ද?", "පැලීම් රහිත ඒකාකාරී ස්ඵටික ව්‍යුහයක් ඇති ගල් පර්වත තෝරා ගැනීම", "දිය පාරේ පාවී ආ වැලි ගල් පමණක් ගැනීම", "කුඩා මැටි කැට එකට ඇලවීම", "හුණු මැටි පමණක් කැටයම් කිරීම", "අවුකන වැනි දැවැන්ත මූර්ති කැඩී නොයන ලෙස ඝන පැලීම් රහිත ග්නයිස් පර්වත තෝරාගෙන ඇත."),
        q("අනුරාධපුර සඳකඩපහණෙහි 'ලියවැල් මෝස්තරය' (Liya-vela) මගින් සංකේතවත් කෙරෙන බෞද්ධ සංකල්පය කුමක්ද?", "නොනවතින තෘෂ්ණාව හා භව බැඳීම", "වන සංරක්ෂණ නීතිය", "උද්‍යාන වගා ක්‍රමවේදය", "සංගීත තාල රටාව", "එතෙමින් දිගටම වැඩෙන වැල සසරට ඇති ආශාව හෙවත් තණ්හාව සංකේතවත් කරන බව විද්වත් මතයයි."),
        q("අනුරාධපුරයේ 'රත්නප්‍රාසාද මුරගල' නිර්මාණය වූයේ කුමන සියවසේදී පමණද?", "ක්‍රි.ව. 8 වන සියවසේදී පමණ", "ක්‍රි.ව. 18 වන සියවසේදී", "ක්‍රි.පූ. 5 වන සියවසේදී", "ක්‍රි.ව. 20 වන සියවසේදී", "අභයගිරියට අයත් රත්නප්‍රාසාදයේ අගනා මුරගල ක්‍රි.ව. 8 වන සියවසේ පසු අනුරාධපුර කලාව නියෝජනය කරයි."),
        q("අනුරාධපුර යුගයේ 'කැටයම් කලාවේ' දක්නට ලැබෙන 'වාමන රූප' (Gana) බොහෝ විට නෙළා ඇත්තේ කුමන ආකාරයකටද?", "තරබාරු කුඩා සිරුරකින් හා සතුටින් නටන හෝ වාදනය කරන අයුරින්", "උස කෙට්ටු භයානක යෝධයන් ලෙස", "ඔටුණු පැළඳි බුදු රූප ලෙස", "පියාපත් ඇති රාජාලීන් ලෙස", "බර උසුලන හා නටන තරබාරු කුඩා ගණ රූප කැටයමට ජීවය හා සතුට එක් කරයි."),
        q("අනුරාධපුර යුගයේ මූර්ති හා කැටයම් කලාව සමස්තයක් ලෙස හැඳින්විය හැකි නිවැරදි විශේෂණ පද මොනවාද?", "සම්භාව්‍ය, සංයමශීලී, ගාම්භීර හා ආධ්‍යාත්මික", "විකට, අසංවර, කලබලකාරී හා රළු", "වියුක්ත, යාන්ත්‍රික හා කෘත්‍රිම", "වෙළඳ, කාර්මික හා නාගරික", "සියවස් ගණනක් පුරා පෝෂණය වූ අනුරාධපුර මූර්ති කලාව ගැඹුරු ආධ්‍යාත්මික සංයමයෙන් යුක්තය."),
        q("අනුරාධපුර 'මහසෙන් මන්දිරය' අබියස ඇති සඳකඩපහණෙහි සතුන් සතර දෙනා දුවන දිශාව කෙබඳුද?", "වමේ සිට දකුණට (දක්ෂිණාවර්තව) ගමන් කරන ආකාරයට", "දකුණේ සිට වමට පමණක්", "එකිනෙකාට විරුද්ධව හිස ගැටෙන ලෙස", "මැදට හිස යොමා නිදා සිටින ලෙස", "බෞද්ධ සම්ප්‍රදායේ ප්‍රදක්ෂිණා ගමනට අනුකූලව සතුන් පෙළ දක්ෂිණාවර්තව ගමන් කරනු කැටයම් කර ඇත."),
        q("අනුරාධපුර යුගයේ 'වැලිගම කුෂ්ඨරාජගල' හා 'බුදුරුවගල' මූර්ති අතර පොදු වන්නේ කුමන කරුණද?", "පිහිටි ගල් පර්වතවල නෙළූ මහායාන බෝධිසත්ව මූර්ති වීම", "දෙකම කුඩා ලෝකඩ පිළිම වීම", "දෙකම මහනුවර යුගයේ දැව කැටයම් වීම", "දෙකෙහිම සිංහල කවි ලියා තිබීම", "ක්‍රි.ව. 8–10 සියවස්වල මහායාන බෞද්ධ ආගමික ප්‍රබෝධය මෙම දැවැන්ත පර්වත මූර්තිවලින් පෙනේ."),
        q("අනුරාධපුර යුගයේ 'වටදාගේ' වටා ඇති ශිලා කැටයම් වැටවල් හෙවත් 'වේදිකා' ආශ්‍රිත කැටයම් ආභාසය ලබා ඇත්තේ කුමකින්ද?", "දැව වැට හා සාංචි තොරණ් ආභාසය", "ග්‍රීක රෝම යකඩ වැටවල්", "බ්‍රිතාන්‍ය පාර්ලිමේන්තු ගොඩනැගිලි", "චීන මහා ප්‍රාකාරය", "මුලදී ලීයෙන් තැනූ වැටවල් පසුව ඒ හැඩයටම කළුගලින් නෙළීම පැරණි වාස්තු පරිණාමයකි."),
        q("අනුරාධපුර 'මිරිසවැටිය' හෝ 'අභයගිරිය' වාහල්කඩවල ඇති 'කල්ප වෘක්ෂය' හා 'පුන් කලස' කැටයම්වලින් පෙන්වන්නේ කුමක්ද?", "ලෝකෝත්තර පූජාව හා අනන්ත සෞභාග්‍යය", "යුද බලය පැතිරවීම", "වනාන්තර කපා හෙළීම", "බදු අය කිරීමේ ක්‍රමය", "සිතූ පැතූ සම්පත් දෙන කල්ප වෘක්ෂය හා පුන්කලස ශ්‍රී සමෘද්ධිය සංකේතවත් කරයි."),
        q("අනුරාධපුර යුගයේ 'බුදු පිළිමවල පාද පීඨය' යටින් නිතර දක්නට ලැබෙන කැටයම කුමක්ද?", "සිංහ රූප හෝ නෙළුම් මල් පෙති", "කුරුල්ලන් හා මසුන්", "ගොවි උපකරණ", "රථ රෝද හා අශ්වයන්", "පද්ම පීඨය මත හෝ ශාක්‍යසිංහ ගෞරවය හඟවන සිංහාසන පීඨය මත බුදු රූප පිහිටුවා ඇත."),
        q("ඉසුරුමුණියේ 'මිනිසා සහ අශ්ව හිස' කැටයමේ අශ්වයාගේ හිස නෙළා ඇති ඉරියව්ව පුරුෂයාගේ ඉරියව්ව සමඟ ගැළපෙන්නේ කෙසේද?", "පුරුෂයා ඉදිරිය බලා සිතමින් සිටින විට උරහිසට ඉහළින් අශ්ව හිස එබී බලන සේ", "අශ්වයා පුරුෂයාගේ පාද යට වැටී සිටින සේ", "පුරුෂයා අශ්වයා පිට නැගී දුවන සේ", "අශ්වයා ඉවතට හැරී පලා යන සේ", "මිනිසාගේ උරහිසට පිටුපසින් අශ්ව හිස මතු වීම කැටයමට අභිරහස් ගාම්භීර බවක් එක් කරයි."),
        q("අනුරාධපුර යුගයේ ලෝකඩ ප්‍රතිමාවක් වන 'වෙහෙරගල බෝධිසත්ව රුවේ' දක්නට ලැබෙන ඉරියව්ව හා මුද්‍රාව කුමක්ද?", "ලලිතාසනය හා කටක-විතර්ක මුද්‍රා", "හිටගෙන අසිපතක් දරා සිටීම", "සැතපී නිදා සිටීම", "දෙඅත් හිස මත තබා නැටීම", "අවලෝකිතේශ්වර බෝසත් රුව මෘදු නැමීමකින් යුතුව ලලිතාසනයෙන් වැඩ සිටිනු නිමවා ඇත."),
        q("අනුරාධපුර යුගයේ 'මහා බුදු පිළිමවල' හිසෙහි ඇති කෙස් කැරලි නෙළීමේදී ශිල්පියා භාවිත කළ ක්‍රමය කුමක්ද?", "සමමිතික ගොළුබෙලි හිසකෙස් කැරලි", "තාර ගා හිස කළු කිරීම", "සිහින් ලෝහ කම්බි ඇලවීම", "හිසෙහි කැටයම් නොකිරීම", "සෑම කෙස් කැරැල්ලක්ම දකුණට කැරකුණු ඒකාකාර රටාවකින් ගලේම නෙළා ඇත."),
        q("අනුරාධපුර යුගයේ 'බුදු පිළිමයක සිරුරේ ඇඳුම' (චීවරය) නෙළන ලද ප්‍රධාන ශෛලීන් දෙක මොනවාද?", "රැලි රහිත සිනිඳු ඇලුණු චීවර ශෛලිය හා රැලි සහිත චීවර ශෛලිය", "රන් කොටු චීවරය හා මල් චීවරය", "සමතලා කළු චීවරය හා නිල් චීවරය", "වීදුරු ආලේපිත චීවරය හා රෙදි චීවරය", "සමාධි පිළිමයේ සිනිඳු චීවරයත් අවුකන පිළිමයේ රැලි සහිත චීවරයත් ප්‍රධාන ශෛලීන් දෙකයි."),
        q("අනුරාධපුර 'මිහින්තලේ රජමහා විහාරය' අසල 'ගිරිභණ්ඩ සෑය' හෝ චේතියගිරිය ආශ්‍රිත කැටයම් මගින් පෙනෙන්නේ කුමක්ද?", "දාගැබ් හා ආරාම ගල් කැටයම්", "පෘතුගීසි බලකොටු ඉදිකිරීම්", "නූතන සිමෙන්ති සැරසිලි", "බැරොක් කැටයම් කලාව", "ලංකාවේ මුල්ම බෞද්ධ ස්තූප ආශ්‍රිතව ශිලා කැටයම් දියුණු වූ අයුරු එහිදී දැකිය හැක."),
        q("අනුරාධපුර යුගයේ 'කැටයම් ශිල්පියා' කළුගලේ තද බව හා මෘදු හැඟීම් අතර සමබරතාව පවත්වා ගත්තේ කෙසේද?", "ඔප දැමූ වක්‍ර තල හා සියුම් රේඛා", "ගල් මත රෙදි ඇලවීම", "තෙල් සායමින් රූප ඇඳීම", "ගල් පුවරු කඩා ඇලවීම", "ඉසුරුමුණි පෙම් යුවළ හා රත්නප්‍රාසාද මුරගල ඔප දැමූ වක්‍රතා හා සියුම් කැටයම් රේඛාවලින් සමන්විතය."),
        q("අනුරාධපුර සඳකඩපහණේ 'සිංහයා, අශ්වයා, ඇතා හා ගවයා' යන සතුන් තෝරා ගැනීමට බලපෑ තවත් ඉන්දීය ආභාසයක් වන්නේ කුමක්ද?", "සාරානාත් අශෝක ස්තම්භ හිසෙහි ඇති සතර සතුන්ගේ සංකේතය", "චීන රාශි චක්‍රයේ සතුන්", "ඊජිප්තු ස්පින්ක්ස් හා හිපපොටේමස්", "ග්‍රීක මිනෝටෝර් කතා", "ධර්ම චක්‍රය සමඟ සාරානාත් අශෝක කුළුණේද මෙම සතුන් සතර දෙනාම කැටයම් කර තිබීම කැපී පෙනේ."),
        q("අනුරාධපුර යුගයේ 'මුරගල' පිළිබඳව අධ්‍යයනය කිරීමේදී එහි ප්‍රායෝගික හා කලාත්මක අරමුණු දෙක කුමක්ද?", "කොරවක්ගල ආධාරකය ලෙස ක්‍රියා කිරීම හා ආරක්ෂාව-සෞභාග්‍යය පෙන්වීම", "බුදු රුව වැඳීම හා මල් පූජා කිරීම", "පහන් දැල්වීම හා වතුර ගබඩා කිරීම", "ලිපි ලේඛන කෙටීම හා බදු ගණන් කිරීම", "ව්‍යුහාත්මකව පියගැටපෙළ අත්වැල නතර කරන අතර ආගමිකව පිවිසුම ආරක්ෂා කරන සංකේතයකි."),
        q("අනුරාධපුර 'තොලුවිල' හා 'පංකුලිය' පිළිම අතර 'හිඳි ඉරියව්වේ' ඇති සමානකම කුමක්ද?", "දෙකම පාද එක මත එක තැබූ වීරාසන හිඳි ඉරියව්වෙන් යුක්ත වීම", "දෙකම පුටුවක වාඩි වී සිටින භද්‍රාසනය වීම", "දෙකම සැතපෙන ඉරියව්වෙන් තිබීම", "දෙකම නැගිට සිටින ඉරියව්ව වීම", "අනුරාධපුරයේ බහුලව භාවිත කළ වීරාසනය මෙම හිඳි බුදු පිළිම දෙකෙහිම පොදුය."),
        q("අනුරාධපුර යුගයේ මූර්ති කලාවේ 'මුහුණේ මඳ සිනහව' (Archaic/Serene smile) මගින් දැක්වෙන අධ්‍යාත්මික තත්ත්වය කුමක්ද?", "සියලු කෙලෙස් නැසූ ප්‍රඥාවේ හා මෛත්‍රියේ අභ්‍යන්තර තෘප්තිය", "නරඹන්නාට සමච්චල් කිරීමේ හාස්‍යය", "මූර්ති ශිල්පියාගේ දත් කැටයම් කිරීමේ අසමත් බව", "භෞතික ලෞකික සැපතට ඇති ආශාව", "අතිශය සියුම්ව නෙළූ තොල්වල නැමීම තුළින් කරුණාව හා නිරාමිස ප්‍රීතිය ප්‍රකාශ වේ."),
        q("අනුරාධපුර යුගයේ 'වටදාගේ' වල පිටත බැම්මේ කැටයම් කර තිබූ සැරසිලි මෝස්තරය කුමක්ද?", "හතරැස් කොටු හා පිපුණු නෙළුම් මල් පදක්කම් (Lotus Medallions)", "ගිනි කඳු හා මුහුදු රළ රටා", "රෝම අකුරු හා ඉලක්කම්", "මහනුවර භේරුණ්ඩ පක්ෂීන්", "මැදිරිගිරිය හා තිරියාය වටදාගෙවල්වල ගල් වැටේ නෙළුම් මල් පදක්කම් කැටයම් ඉතා ප්‍රකටය."),
        q("අනුරාධපුර යුගයේ කලාකෘතියක් වන 'නටන ගණ රූප කැටයම්' දැකිය හැකි ප්‍රසිද්ධ ස්ථාන මොනවාද?", "මිහින්තලේ කණ්ඨක චේතිය හා අනුරාධපුර අභයගිරි/ජේතවන වාහල්කඩ", "සීගිරියේ කැටපත් පවුර මත", "දඹුල්ලේ විහාර වහලය මත", "මාලිගාවිල වැව් බැම්ම මත", "වාහල්කඩ තීරුවල හා පඩිපෙළ සිරස් මුහුණත්වල නටන හා වයන ගණ රූප දක්නට ලැබේ."),
        q("අනුරාධපුරයේ 'රුවන්වැලිසෑය' ආශ්‍රිත කෞතුකාගාරයේ ඇති කුඩා ශිලා හා මැටි මූර්තිවලින් හෙළි වන්නේ කුමක්ද?", "සාමාන්‍ය ජන ජීවිතය, කාන්තා විලාසිතා හා සත්ව නිරූපණ කෙරෙහි තිබූ උනන්දුව", "මූර්ති කලාව විදේශිකයන්ට තහනම් වූ බව", "මැටි පිළිස්සීමේ කලාව නොතිබූ බව", "යුරෝපීය යුද උපකරණ තැනූ බව", "ගැමි හා නාගරික සමාජයේ විවිධ අංග පිළිබිඹු කරන මැටි රූප හා පුංචි කැටයම් හමු වී ඇත."),
        q("අනුරාධපුර යුගයේ 'බුදු පිළිමවල උරහිස් හා පපුව' පුළුල්ව ශක්තිමත්ව නෙළීමෙන් නිරූපණය කර ඇත්තේ කුමක්ද?", "සිංහ රාජයෙකුගේ වැනි පූර්වකාය හෙවත් මහාපුරුෂ තේජස", "කායවර්ධන ක්‍රීඩා තරගකරුවෙකුගේ සිරුර", "යුද සෙබළෙකුගේ යකඩ සන්නාහය", "ගලේ ඉඩ පිරවීමේ අවශ්‍යතාව", "දෙතිස් මහාපුරුෂ ලක්ෂණවල එන 'සීහපුබ්බද්ධකාය' (සිංහයෙකුගේ ඉදිරිකය වැනි) ගුණය ඉන් දැක්වේ."),
        q("අනුරාධපුර 'අවුකන බුදු පිළිමයේ' උරහිස මත ඇති චීවර පොටේ රැලි හැසිරවීමේදී ශිල්පියා දක්වා ඇති දක්ෂතාව කුමක්ද?", "සිනිඳු රෙදි රැලි කළුගලින් මැවීම", "රැලි සියල්ල කෙළින් ඉරි ලෙස කැපීම", "සිවුර වෙනුවට සත්ව හමක් නෙළීම", "රැලි මත තෙල් සායම් ගෑම", "අඩි 40ක් උස කළුගලේ පවා රෙද්දක මෘදු රැලි පෙනෙන සේ නෙළීම අසමසම දක්ෂතාවයකි."),
        q("අනුරාධපුර යුගයේ 'මුරගල, කොරවක්ගල, සඳකඩපහණ' යන කැටයම් මගින් විහාරයකට ඇතුළු වන බැතිමතා තුළ ඇති කරන මානසික තත්ත්වය කුමක්ද?", "ලෞකික බැඳීම්වලින් මිදී ශාන්ත පූජනීය බවට පිවිසීමේ හැඟීම", "බිය ගැන්වී ආපසු හැරී යාමේ හැඟීම", "රාජ්‍ය නීති කඩ කිරීමේ පෙළඹවීම", "වෙළඳ ගනුදෙනු කිරීමේ ආශාව", "සඳකඩපහණේ සංසාර චක්‍රය පාගා මුරගල් මැදින් පිවිසීම ආධ්‍යාත්මික සූදානමක් ඇති කරයි."),
        q("අනුරාධපුර 'මාලිගාවිල' බුදු පිළිමය පිහිටි ස්ථානයෙන් තවත් කුමන දැවැන්ත බෝසත් ප්‍රතිමාවක් හමු වී ඇත්ද?", "දඹේගොඩ අවලෝකිතේශ්වර බෝධිසත්ව ප්‍රතිමාව", "පොළොන්නරුවේ පරාක්‍රමබාහු ප්‍රතිමාව", "මහනුවර පත්තිනි දේව ප්‍රතිමාව", "ගාල්ලේ විෂ්ණු දේව ප්‍රතිමාව", "මාලිගාවිල ආසන්නයේම දඹේගොඩ පිහිටි මීටර් 10ක් පමණ උස බෝසත් පිළිමයද පුනරුත්ථාපනය කර ඇත."),
        q("දඹේගොඩ අවලෝකිතේශ්වර බෝසත් ප්‍රතිමාවේ විශේෂත්වය කුමක්ද?", "මීටර් 10කට ආසන්න වටකුරු පාෂාණ බෝසත් පිළිමයක් හා ජටා මකුටයකින් යුක්ත වීම", "එය ඉතා කුඩා ඇත්දත් රුවක් වීම", "එය ගඩොල්වලින් පමණක් තැනීම", "එය මුහුදු පතුලෙන් හමු වීම", "මහායාන සම්ප්‍රදායේ උසම නිදහස් බෝධිසත්ව මූර්තියක් ලෙස දඹේගොඩ ප්‍රතිමාව වැදගත් වේ."),
        q("අනුරාධපුර යුගයේ 'වැලිගම කුෂ්ඨරාජගල' ප්‍රතිමාවේ අත් සතරෙන් හෝ දෙඅතින් දක්වන මුද්‍රාව කුමක්ද?", "සිංහනාද හෝ කටක-විතර්ක මුද්‍රා", "ධ්‍යාන මුද්‍රාව පමණක්", "භූමිස්පර්ශ මුද්‍රාව පමණක්", "කඩු පළිහ දරා සිටීම", "රෝග සුව කරන කරුණා ස්වරූපය හා ආභරණ සහිත සම්භාව්‍ය බෝධිසත්ව ලක්ෂණ එහි වේ."),
        q("අනුරාධපුර යුගයේ මූර්ති කලාවේ 'මුහුණු ලක්ෂණ' හා 'ශරීර ලාලිත්‍යය' පිළිබඳව අධ්‍යයනයේදී වැදගත්ම සාධකය කුමක්ද?", "භෞතික මාංශපේශී අතිශයෝක්තියෙන් පෙන්වීම වෙනුවට සිනිඳු පිරිපුන් බව දැක්වීම", "ග්‍රීක මූර්ති මෙන් සෑම නහරයක් හා මාංශපේශියක්ම පෙන්වීම", "මිනිස් සිරුර ජ්‍යාමිතික කැබලිවලට කැඩීම", "සියලු ප්‍රතිමාවලට රැවුල නෙළීම", "ඉන්දීය හා හෙළ මූර්ති රීතිය අනුව අධ්‍යාත්මික ශක්තිය සිනිඳු සමමිතික හැඩයෙන් පෙන්වයි."),
        q("අනුරාධපුර යුගයේ 'වටදාගේ' වල ඇති ශිලා කුළුණු පිහිටුවා ඇති ජ්‍යාමිතික රටාව කුමක්ද?", "ස්තූපය වටා සමකේන්ද්‍රීය වෘත්ත (Concentric Circles) ලෙස", "දිග සෘජුකෝණාස්‍රාකාර පේළි දෙකක් ලෙස", "ත්‍රිකෝණාකාර පිරමීඩ හැඩයට", "අක්‍රමවත් වංගු රේඛාවක් ලෙස", "දාගැබ කේන්ද්‍ර කර ගෙන වටේට කේන්ද්‍රීය වළලු ආකාරයෙන් ගල් කුළුණු සිටුවා ඇත."),
        q("අනුරාධපුර යුගයේ 'පංකුලිය' බුදු පිළිමයේ ඇස් කුහරවල මුල් කාලයේ තිබූ බව සැලකෙන විශේෂත්වය කුමක්ද?", "මැණික් හෝ රන් ඔබ්බවා තිබීම", "ඇස් හිස් සිදුරු ලෙස තැබීම", "වීදුරු බෝල දමා තිබීම", "වතුර පිරවූ කුහර වීම", "ඇතැම් ප්‍රතිමාවල නේත්‍ර ප්‍රතිෂ්ඨාපන මංගල්‍යයේදී වටිනා පාෂාණ හෝ වර්ණක ඇස් මත යොදා තිබිණි."),
        q("අනුරාධපුර යුගයේ 'කැටයම් ශිල්පීන්' ලබාගත් පුහුණුව හා සංවිධානය කෙබඳු වීද?", "පරම්පරාගත ශිල්පීය ශ්‍රේණි හා රාජකාරි ක්‍රමය යටතේ පුහුණුවීම", "විදේශීය අන්තර්ජාල පාඨමාලා මගින්", "වසරක කෙටි වැඩමුළු මගින් පමණක්", "කිසිදු පුහුණුවක් නොමැතිව අහම්බෙන්", "ශිල්පීය කුල හා ගුරුකුල මගින් පරම්පරා ගණනාවක් තිස්සේ මූර්ති ශිල්පය පවත්වා ගෙන ආහ."),
        q("අනුරාධපුර යුගයේ 'තාරා දේවි' ලෝකඩ ප්‍රතිමාවේ පිහිටි නළලේ කුඩා කුහරය කුමක් සඳහා භාවිත කළ බව සැලකේද?", "වටිනා මැණිකක් හෝ තිලකයක් ඔබ්බවා තැබීමට", "වැසි වතුර බැස යාමට", "දූවිලි පිස දැමීමට", "ඇණයක් ගසා බිත්තියේ එල්ලීමට", "හිස් පළඳනාවේ හෝ නළලේ වටිනා මැණිකක් ඔබ්බවා තිබූ බව කලා විචාරකයන්ගේ අදහසයි."),
        q("අනුරාධපුර 'ඉසුරුමුණියේ පෙම් යුවළ' මූර්තිය ස්ථානගත කර තිබුණේ මුල් කාලයේ කොතැනකද?", "රන්මසු උයන අසල බිත්තියක", "මහනුවර දළදා මාලිගයේ", "කතරගම දේවාලයේ", "සීගිරි ගල මුදුනේ", "ඉසුරුමුණි විහාර පරිශ්‍රයේ හා රන්මසු උයන ආසන්නයේ පැවති පුවරු පසුව කෞතුකාගාරයේ සුරැකිණි."),
        q("අනුරාධපුර යුගයේ 'රජුන් හා දෙවිවරුන්' වෙනුවට සාමාන්‍ය ජන රූප බහුලව කැටයම් කර ඇත්තේ කුමන ස්ථානවලද?", "වාහල්කඩ හා පියගැටපෙළ ගණ රූප තීරුවල", "සමාධි පිළිමයේ පපුව මත", "සිරිපතුල් ගල මත", "යන්ත්‍ර ගල් ඇතුළත", "බෙර වයන, නටන, හිසින් බර උසුලන සාමාන්‍ය හා ගණ රූප වාහල්කඩ තීරුවල හමුවේ."),
        q("අනුරාධපුර යුගයේ 'කැටයම් මෝස්තර' අතර බහුලව භාවිත කළ ජ්‍යාමිතික හා උද්භිද සැරසිලි දෙකක් මොනවාද?", "පලාපෙති සහ ලියවැල්", "ත්‍රිකෝණමිතික ප්‍රස්තාර සහ සර්පිල කොටු", "වෘත්තාකාර දැති රෝද සහ ඉස්කුරුප්පු", "අරාබි අක්ෂර සහ කුරුස", "පලාපෙති, ලියවැල් සහ පුන්කලස් අනුරාධපුරයේ සිට මහනුවර දක්වාම විහිදුණු පොදු සැරසිලි වේ."),
        q("අනුරාධපුරයේ 'සමාධි පිළිමය' හා 'අවුකන පිළිමය' අතර ප්‍රධාන වෙනස්කම් තුන කවරේද?", "ඉරියව්ව (හිඳි/හිටි), පාෂාණය (ඩොලමයිට්/ග්නයිස්) හා චීවර රැලි (රහිත/සහිත)", "රට (ලංකාව/ඉන්දියාව), කාලය (නූතන/ආදි) හා වර්ණය", "මූර්ති වර්ගය (ලෝකඩ/මැටි) හා ප්‍රමාණය", "වෙනසක් නැත; දෙකම එකම අච්චුවේ පිළිම වේ", "ඉරියව්ව, භාවිත ගල් වර්ගය හා සිවුරු රැලි ක්‍රමය යන තුනම මෙම පිළිම දෙකෙහි පැහැදිලිව වෙනස්ය."),
        q("අනුරාධපුර යුගයේ 'වෙහෙරගල' හා 'තාරා' ප්‍රතිමා මගින් පෙනෙන ලෝහ කලාවේ උසස් ගුණය කුමක්ද?", "සියුම් ශරීර හැඩතල, රන් ආලේපන තාක්ෂණය හා ආභරණ කැටයම", "රළු වෑල්ඩින් පෑස්සුම් සලකුණු", "ලෝහ මලකඩ කෑම වැළැක්වීමට තාර ගෑම", "විශාල ගල් කැබලි ලෝහයට ඇලවීම", "මිශ්‍ර ලෝහ සංයුතිය හා ඉටි මැකුම් ක්‍රමයේ නිරවද්‍යතාව මෙම ප්‍රතිමාවලින් තහවුරු වේ."),
        q("අනුරාධපුර යුගයේ මූර්ති කලා උරුමය O/L ශිෂ්‍යයෙකු විසින් අගය කළ යුත්තේ කුමන දෘෂ්ටිකෝණයකින්ද?", "තාක්ෂණික දැනුම, ආධ්‍යාත්මික සංයමය හා දේශීය සංස්කෘතික අනන්‍යතාව අනුව", "මූර්තිවල මූල්‍ය වෙළඳපොළ වටිනාකම අනුව පමණක්", "කැඩුණු කොටස් ගණන ගණන් කිරීමෙන් පමණක්", "යුරෝපීය කලාවට වඩා පහත් කොට සැලකීමෙන්", "ගලෙන් හා ලෝකඩෙන් ජීවමාන ශාන්තිය මැවූ හෙළ ශිල්පියාගේ ප්‍රතිභාව විචාරාත්මකව අගය කළ යුතුය."),
        q("අනුරාධපුර 'රත්නප්‍රාසාද මුරගලේ' නාගරාජ රුවෙහි ශරීරය පිහිටා ඇති විලාසය හඳුන්වන්නේ කුමන නමින්ද?", "ත්‍රිභංග ඉරියව්ව", "ශයන ඉරියව්ව", "සමභංග ඉරියව්ව", "උත්කුටුක ඉරියව්ව", "හිස, කඳ සහ උකුළ තුන් තැනකින් මෘදුව නැමුණු ත්‍රිභංග ඉරියව්ව මුරගලට ජීවමාන ලාලිත්‍යයක් දෙයි."),
        q("අනුරාධපුර 'ඉසුරුමුණියේ ඇතුන් කැටයම' පිහිටි ස්ථානයේ පාරිසරික අලංකරණය වැඩි දියුණු කර ඇත්තේ කෙසේද?", "කැටයමට පහළින් පිහිටි ජල පොකුණේ ඇතුන් සෙවණැලි පතිත වන සේ නිර්මාණය කිරීමෙන්", "පොකුණ සම්පූර්ණයෙන් පස් පුරවා වැසීමෙන්", "කැටයම වටා විශාල යකඩ වැටක් ඉදිකිරීමෙන්", "ඇතුන් මත තෙල් සායම් ආලේප කිරීමෙන්", "පොකුණේ ජලයත් ගල් පර්වතයේ ඇතුන් රූපත් එකිනෙකට සමබරව ස්වභාවික දසුනක් මවයි."),
        q("අනුරාධපුර යුගයේ 'බුදු පිළිම කලාව' පිළිබඳව ආනන්ද කුමාරස්වාමි මහතා දක්වා ඇති ප්‍රධාන විචාරාත්මක අදහස කුමක්ද?", "සමාධි පිළිමය ආසියානු බෞද්ධ කලාවේ ශ්‍රේෂ්ඨතම ප්‍රකාශනයක් බව", "අනුරාධපුර පිළිම සියල්ල ග්‍රීක ශිල්පීන්ගේ බව", "පිළිමවල කිසිදු ශිල්පීය වටිනාකමක් නොමැති බව", "පිළිම කලාව ඇරඹුණේ 19 වන සියවසේ බව", "ආචාර්ය ආනන්ද කුමාරස්වාමි තුමා සමාධි පිළිමයේ අධ්‍යාත්මික නිහඬ බව ලොවට හඳුන්වා දුන්නේය."),
        q("අනුරාධපුර යුගයේ 'කැටයම් කළ පියගැටපෙළ' (Moonstone to Moonstone stairs) පද්ධතිය තුළ ඇති සමස්ත අලංකරණ අංග කීයක්ද?", "සඳකඩපහණ, මුරගල් හා කොරවක්ගල්", "තනි කළුගල් පඩියක් පමණි", "මකර තොරණක් පමණි", "වීදුරු දොරක් හා යකඩ වැටක්", "මෙම සියලු අංග එක්ව පූජනීය ගොඩනැගිල්ලක පිවිසුම සම්පූර්ණ කලා නිර්මාණයක් බවට පත් කරයි."),
        q("අනුරාධපුර යුගයේ 'මකර තොරණ' කැටයම පසුකාලීනව ශ්‍රී ලංකාවේ කුමන කලා අංගයන්හි දිගටම භාවිත වීද?", "විහාර පිළිමගේ ඇතුළු වීමේ දොරටු හා පිළිම පසුබිම්වල", "කුඹල් මැටි හට්ටි ඇතුළත පමණක්", "කෘෂිකාර්මික නගුල් හා කැතිවල", "නූතන ගුවන් පාලම්වල", "අනුරාධපුර මුරගල් හා කොරවක්ගල්වල ඇරඹි මකර කැටයම පොළොන්නරු හා මහනුවර විහාරවල විශාල තොරණ් විය."),
        q("අනුරාධපුර යුගයේ 'ශිලා කැටයම්වල' නිරූපණය කර ඇති ඇත් රූප (උදා: රුවන්වැලිසෑය, ඉසුරුමුණිය) වල විශේෂ ලක්ෂණය කුමක්ද?", "සතාගේ ස්වාභාවික ශරීර ව්‍යුහය හා චලනය ඉතා නිවැරදිව ගලෙන් මතු කිරීම", "ඇතුන්ට කුරුලු පියාපත් ඇඳ තිබීම", "ඇතුන් සතරැස් පෙට්ටි ලෙස නෙළීම", "ඇතුන්ගේ හොඬවැල නොනෙළා තැබීම", "ශ්‍රී ලංකාවේ කලාකරුවාට ඇතුන් හොඳින් හුරුපුරුදු වූ හෙයින් ඉතා ජීවමානව ඇත් රූප නෙළා ඇත."),
        q("අනුරාධපුර යුගයේ මූර්ති හා කැටයම් කලාව අධ්‍යයනයේදී 'පල්ලව ආභාසය' වඩාත් පැහැදිලිව හඳුනාගත හැකි නිර්මාණය කුමක්ද?", "ඉසුරුමුණියේ මිනිසා සහ අශ්ව හිස හා දිය කෙළින ඇතුන්", "රුවන්වැලිසෑයේ මහා කොත", "මහනුවර ඇම්බැක්කේ ලී කණු", "ගාල්ලේ ඔරලෝසු කණුව", "ක්‍රි.ව. 7 වන සියවසේ ඉන්දියානු පල්ලව කලා ලක්ෂණ ඉසුරුමුණියේ පර්වත කැටයම්වල පැහැදිලිව දිස්වේ."),
        q("අනුරාධපුර 'මාලිගාවිල' හා 'අවුකන' ප්‍රතිමා සැසඳීමේදී පෙනෙන තාක්ෂණික වෙනස කුමක්ද?", "මාලිගාවිල සම්පූර්ණ වටකුරු පිළිමයක් වන අතර අවුකන පර්වතයට බැඳි පිළිමයකි", "මාලිගාවිල ලෝකඩ වන අතර අවුකන මැටියෙන් තනා ඇත", "අවුකන සැතපෙන අතර මාලිගාවිල හිඳි පිළිමයකි", "දෙකම මීටරයක් පමණ කුඩා ප්‍රතිමා වේ", "සම්පූර්ණයෙන්ම වෙන් කළ මාලිගාවිල හා පිටුපසින් බැඳි අවුකන අතර මූලික ශිල්පීය වෙනස මෙයයි.")
    )
}
